function validate(input) {
  const [{ Employees = [] }] = input;
  const seen = new Set();
  for (const [id, , , age] of Employees) {
    if (id === null) return 'Every employee needs an employee_id.';
    if (seen.has(id)) return `employee_id ${id} appears twice.`;
    seen.add(id);
    if (age === null || age < 0) return `Employee ${id} needs a non-negative age.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const names = ['Hercy', 'Alice', 'Bob', 'Winston', 'Michael', 'Eve', 'Grace', 'Frank'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const pool = size === 'small' ? 12 : 2000;
  // Distinct ids in shuffled order, so the output order must come from ORDER BY.
  const ids = Array.from({ length: pool }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const chosen = ids.slice(0, count);
  // In large cases a few bosses take most reports, so groups are big; small cases mix nulls and chains.
  const bosses = chosen.slice(0, Math.max(1, Math.floor(count / 20)));
  const Employees = chosen.map(id => {
    let boss = null;
    if (rand() < 0.7 && count > 1) {
      boss = size === 'large' && rand() < 0.5 ? pick(bosses) : pick(chosen);
      if (boss === id) boss = null;
    }
    return [id, pick(names), boss, 20 + Math.floor(rand() * 8) * (size === 'small' ? 1 : 5)];
  });
  return [{ Employees }];
}
